//! The WING parameter tree: every node's name, numeric id, type, unit, range
//! and choices, as the console's remote protocols and snapshot files use them.
//!
//! The data (`data/wing_tree.bin`) is generated by `tools/wing/gen_tree.py`
//! from the parameter sweep in libwing (Apache-2.0, `propmap.jsonl`, WING
//! firmware 3.1). Model parameters (a gate's THR, an FX device's DECAY, ...)
//! are children of their slot on the console (`/ch/1/gate/thr`) and change
//! with the slot's model, so they are stored per slot family ("templates") and
//! resolved through a [`ModelSource`] that knows each slot's active model.
//!
//! The custom controls' keys and encoders (`/$ctl/user/.../bu`, `bd`, `enc`)
//! work the same way: their `mode` is the model, and the function's targets
//! and options (`ch`, `fx`, `par`, `other`, ...; WING remote protocols, the
//! "<OSC b_pattern>" and "<OSC e_pattern>" tables) are its parameters, one id
//! per position for every mode. The sweep caught only the modes its console
//! had set, so those slots are added here from `data/wing_cc_ids.tsv` and the
//! protocol document's tables ([`Schema::cc_mode_row`]).

use std::borrow::Cow;
use std::collections::HashMap;
use std::sync::OnceLock;

static BLOB: &[u8] = include_bytes!("../data/wing_tree.bin");
static CC_IDS: &str = include_str!("../data/wing_cc_ids.tsv");

/// "No parent": the row is a child of the root.
pub const NO_PARENT: u16 = 0xffff;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NodeType {
    Node,
    LinFloat,
    LogFloat,
    Fader,
    Int,
    StrEnum,
    FloatEnum,
    Str,
}

impl NodeType {
    fn from_u8(v: u8) -> Self {
        match v {
            1 => Self::LinFloat,
            2 => Self::LogFloat,
            3 => Self::Fader,
            4 => Self::Int,
            5 => Self::StrEnum,
            6 => Self::FloatEnum,
            7 => Self::Str,
            _ => Self::Node,
        }
    }

    /// The type nibble of the Native protocol's node flags.
    pub fn wire(self) -> u8 {
        match self {
            Self::Node => 0,
            Self::LinFloat => 1,
            Self::LogFloat => 2,
            Self::Fader => 3,
            Self::Int => 4,
            Self::StrEnum => 5,
            Self::FloatEnum => 6,
            Self::Str => 7,
        }
    }

    pub fn is_float(self) -> bool {
        matches!(self, Self::LinFloat | Self::LogFloat | Self::Fader | Self::FloatEnum)
    }
}

/// Units (the Native protocol's unit nibble).
pub mod unit {
    pub const NONE: u8 = 0;
    pub const DB: u8 = 1;
    pub const PERCENT: u8 = 2;
    pub const MS: u8 = 3;
    pub const HZ: u8 = 4;
    pub const METERS: u8 = 5;
    pub const SECONDS: u8 = 6;
    pub const OCTAVES: u8 = 7;

    pub fn name(u: u8) -> &'static str {
        match u {
            DB => "dB",
            PERCENT => "%",
            MS => "ms",
            HZ => "Hz",
            METERS => "m",
            SECONDS => "s",
            OCTAVES => "oct",
            _ => "",
        }
    }
}

#[derive(Debug)]
pub struct EnumItem {
    pub item: &'static str,
    /// Float enums: the value.
    pub value: f32,
    pub long: &'static str,
}

#[derive(Debug)]
pub struct EnumList {
    pub float: bool,
    pub items: Vec<EnumItem>,
}

/// A node's definition.
#[derive(Debug)]
pub struct Def {
    pub ty: NodeType,
    pub unit: u8,
    pub read_only: bool,
    pub long_name: &'static str,
    /// Floats (and faders): range and step count.
    pub min: f32,
    pub max: f32,
    pub steps: i32,
    pub min_int: i32,
    pub max_int: i32,
    pub max_len: u16,
    pub enum_list: Option<u16>,
}

impl Def {
    /// The choices of an enum (empty for other types).
    pub fn items(&self) -> &'static [EnumItem] {
        match self.enum_list {
            Some(i) => &schema().enums[i as usize].items,
            None => &[],
        }
    }

    pub fn is_leaf(&self) -> bool {
        self.ty != NodeType::Node
    }
}

#[derive(Debug)]
pub struct Row {
    pub parent: u16,
    /// None for nodes addressed by their index ("/ch/1").
    pub name: Option<&'static str>,
    pub index: u16,
    pub def: u16,
    pub id: u32,
}

#[derive(Debug)]
pub struct ModelParam {
    pub name: &'static str,
    /// Position (1-based); the id is the slot's id for this position.
    pub index: u16,
    pub def: u16,
}

#[derive(Debug)]
pub struct Model {
    pub token: &'static str,
    pub params: Vec<ModelParam>,
}

#[derive(Debug)]
pub struct Family {
    pub models: Vec<Model>,
}

#[derive(Debug)]
pub struct Slot {
    /// The slot node ("/ch/1/gate").
    pub row: u16,
    pub family: u16,
    /// Ids of the parameters by position 1.. (0 = unused position).
    pub ids: Vec<u32>,
}

/// A custom control function node (WING remote protocols, the
/// "<OSC b_pattern>" / "<OSC e_pattern>" tables).
struct CcNode {
    name: &'static str,
    long: &'static str,
    values: CcValues,
}

enum CcValues {
    Int(i32, i32),
    Items(&'static [&'static str]),
    /// ("FX", 16): FX1 .. FX16; a count of 0 is the prefix itself.
    Numbered(&'static [(&'static str, i32)]),
    /// The DAW BUTTONS command list of `/$ctl/user/daw1/1/bu/btn`.
    DawButtons,
}

const fn cc(name: &'static str, long: &'static str, values: CcValues) -> CcNode {
    CcNode { name, long, values }
}

