/// A node of the tree. Model parameters are addressed by their slot and
/// position, which is also how the console numbers them.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Node {
    Root,
    Row(u16),
    Param { slot: u16, index: u8 },
}

#[derive(Clone, Copy, Debug)]
enum IdTarget {
    Row(u16),
    Param { slot: u16, index: u8 },
}

/// Knows which model each slot runs (index into its family's models).
pub trait ModelSource {
    fn active_model(&self, slot: u16) -> Option<usize>;
}

/// A source that knows no models (only static nodes resolve).
pub struct NoModels;

impl ModelSource for NoModels {
    fn active_model(&self, _: u16) -> Option<usize> {
        None
    }
}

pub struct Schema {
    pub enums: Vec<EnumList>,
    pub defs: Vec<Def>,
    pub rows: Vec<Row>,
    pub families: Vec<Family>,
    pub slots: Vec<Slot>,
    children: Vec<Vec<u16>>,
    root_children: Vec<u16>,
    slot_of_row: HashMap<u16, u16>,
    by_id: HashMap<u32, IdTarget>,
    /// The custom controls' slots: their `mode` row.
    cc_mode_rows: HashMap<u16, u16>,
    /// The sweep's own rows of custom control function nodes (now the
    /// slots' parameters): kept for their row numbers, no longer children.
    detached: std::collections::HashSet<u16>,
}

/// The tree (parsed once).
pub fn schema() -> &'static Schema {
    static S: OnceLock<Schema> = OnceLock::new();
    S.get_or_init(|| Schema::parse(BLOB).expect("data/wing_tree.bin is damaged"))
}

struct Reader<'a> {
    data: &'a [u8],
    pos: usize,
}

impl Reader<'static> {
    fn take(&mut self, n: usize) -> Option<&'static [u8]> {
        let s = self.data.get(self.pos..self.pos + n)?;
        self.pos += n;
        Some(s)
    }
    fn u8(&mut self) -> Option<u8> {
        Some(self.take(1)?[0])
    }
    fn u16(&mut self) -> Option<u16> {
        Some(u16::from_le_bytes(self.take(2)?.try_into().ok()?))
    }
    fn u32(&mut self) -> Option<u32> {
        Some(u32::from_le_bytes(self.take(4)?.try_into().ok()?))
    }
    fn i32(&mut self) -> Option<i32> {
        Some(self.u32()? as i32)
    }
    fn f32(&mut self) -> Option<f32> {
        Some(f32::from_bits(self.u32()?))
    }
}

impl Schema {
    fn parse(data: &'static [u8]) -> Option<Schema> {
        let mut r = Reader { data, pos: 0 };
        if r.take(4)? != b"LDWT" || r.u32()? != 1 {
            return None;
        }
        let n = r.u32()? as usize;
        let mut strings: Vec<&'static str> = Vec::with_capacity(n);
        for _ in 0..n {
            let len = r.u8()? as usize;
            strings.push(std::str::from_utf8(r.take(len)?).ok()?);
        }
        let st = |i: u16| -> Option<&'static str> {
            if i == 0xffff {
                None
            } else {
                strings.get(i as usize).copied()
            }
        };

        let n = r.u32()? as usize;
        let mut enums = Vec::with_capacity(n);
        for _ in 0..n {
            let float = r.u8()? == 1;
            let count = r.u16()? as usize;
            let mut items = Vec::with_capacity(count);
            for _ in 0..count {
                if float {
                    let value = r.f32()?;
                    let long = st(r.u16()?).unwrap_or("");
                    items.push(EnumItem { item: "", value, long });
                } else {
                    let item = st(r.u16()?).unwrap_or("");
                    let long = st(r.u16()?).unwrap_or("");
                    items.push(EnumItem { item, value: 0.0, long });
                }
            }
            enums.push(EnumList { float, items });
        }

        let n = r.u32()? as usize;
        let mut defs = Vec::with_capacity(n);
        for _ in 0..n {
            let ty = NodeType::from_u8(r.u8()?);
            let unit = r.u8()?;
            let flags = r.u8()?;
            let long_name = st(r.u16()?).unwrap_or("");
            let mut d = Def {
                ty,
                unit,
                read_only: flags & 1 != 0,
                long_name,
                min: 0.0,
                max: 0.0,
                steps: 0,
                min_int: 0,
                max_int: 0,
                max_len: 0,
                enum_list: None,
            };
            match ty {
                NodeType::LinFloat | NodeType::LogFloat | NodeType::Fader if flags & 2 != 0 => {
                    d.min = r.f32()?;
                    d.max = r.f32()?;
                    d.steps = r.i32()?;
                }
                NodeType::Int => {
                    d.min_int = r.i32()?;
                    d.max_int = r.i32()?;
                }
                NodeType::StrEnum | NodeType::FloatEnum => d.enum_list = Some(r.u16()?),
                NodeType::Str => d.max_len = r.u16()?,
                _ => {}
            }
            defs.push(d);
        }

        let n = r.u32()? as usize;
        let mut rows = Vec::with_capacity(n);
        for _ in 0..n {
            let parent = r.u16()?;
            let name = st(r.u16()?);
            let index = r.u16()?;
            let def = r.u16()?;
            let id = r.u32()?;
            rows.push(Row { parent, name, index, def, id });
        }

        let n = r.u32()? as usize;
        let mut families = Vec::with_capacity(n);
        for _ in 0..n {
            let nmodels = r.u16()? as usize;
            let mut models = Vec::with_capacity(nmodels);
            for _ in 0..nmodels {
                let token = st(r.u16()?).unwrap_or("");
                let np = r.u16()? as usize;
                let mut params = Vec::with_capacity(np);
                for _ in 0..np {
                    let name = st(r.u16()?).unwrap_or("");
                    let index = r.u16()?;
                    let def = r.u16()?;
                    params.push(ModelParam { name, index, def });
                }
                models.push(Model { token, params });
            }
            families.push(Family { models });
        }

        let n = r.u32()? as usize;
        let mut slots = Vec::with_capacity(n);
        for _ in 0..n {
            let row = r.u16()?;
            let family = r.u16()?;
            let nids = r.u8()? as usize;
            let mut ids = Vec::with_capacity(nids);
            for _ in 0..nids {
                ids.push(r.u32()?);
            }
            slots.push(Slot { row, family, ids });
        }

        let mut children = vec![Vec::new(); rows.len()];
        let mut root_children = Vec::new();
        let mut by_id = HashMap::with_capacity(rows.len() + slots.len() * 24);
        for (i, row) in rows.iter().enumerate() {
            if row.parent == NO_PARENT {
                root_children.push(i as u16);
            } else {
                children.get_mut(row.parent as usize)?.push(i as u16);
            }
            by_id.entry(row.id).or_insert(IdTarget::Row(i as u16));
        }
        let mut slot_of_row = HashMap::with_capacity(slots.len());
        for (s, slot) in slots.iter().enumerate() {
            slot_of_row.insert(slot.row, s as u16);
            for (k, &id) in slot.ids.iter().enumerate() {
                if id != 0 {
                    by_id.entry(id).or_insert(IdTarget::Param { slot: s as u16, index: k as u8 + 1 });
                }
            }
        }
        let mut s = Schema {
            enums,
            defs,
            rows,
            families,
            slots,
            children,
            root_children,
            slot_of_row,
            by_id,
            cc_mode_rows: HashMap::new(),
            detached: Default::default(),
        };
        s.fix_sweep();
        s.add_cc_slots();
        Some(s)
    }

    /// The custom controls' function nodes as model parameters (see the
    /// module docs): a family for the keys and one for the encoders, whose
    /// models are the `mode` items, and a slot per key and encoder.
    fn add_cc_slots(&mut self) {
        let row = |s: &Schema, path: &str| match s.resolve(path, &NoModels) {
            Some(Node::Row(r)) => Some(r),
            _ => None,
        };
        let (Some(key_mode), Some(enc_mode), Some(daw_btn)) =
            (row(self, "/$ctl/user/1/1/bu/mode"), row(self, "/$ctl/user/1/1/enc/mode"), row(self, "/$ctl/user/daw1/1/bu/btn"))
        else {
            return;
        };
        let daw_btn_def = self.rows[daw_btn as usize].def;
        let family = |s: &mut Schema, mode_row: u16, table: &[(&str, &[CcNode])]| {
            // (Not Def::items: the tree isn't there yet.)
            let list = s.defs[s.rows[mode_row as usize].def as usize].enum_list.map_or(0, usize::from);
            let modes: Vec<&'static str> =
                s.enums.get(list).map(|l| l.items.iter().map(|i| i.item).collect()).unwrap_or_default();
            let models = modes
                .into_iter()
                .map(|token| {
                    let nodes = table.iter().find(|(t, _)| *t == token).map_or(&[][..], |(_, n)| *n);
                    let params = nodes
                        .iter()
                        .enumerate()
                        .map(|(i, n)| ModelParam { name: n.name, index: i as u16 + 1, def: s.cc_def(n, daw_btn_def) })
                        .collect();
                    Model { token, params }
                })
                .collect();
            s.families.push(Family { models });
            (s.families.len() - 1) as u16
        };
        let keys = family(self, key_mode, CC_KEY_NODES);
        let encoders = family(self, enc_mode, CC_ENCODER_NODES);
        for line in CC_IDS.lines().filter(|l| !l.starts_with('#')) {
            let mut fields = line.split('\t');
            let Some(slot_row) = fields.next().and_then(|p| row(self, p)) else { continue };
            let ids: Vec<u32> = fields.filter_map(|f| u32::from_str_radix(f.trim(), 16).ok()).collect();
            let Some(mode_row) = self.child(Node::Row(slot_row), "mode", &NoModels).and_then(|n| match n {
                Node::Row(r) => Some(r),
                _ => None,
            }) else {
                continue;
            };
            let is_encoder = self.rows[slot_row as usize].name == Some("enc");
            // The sweep's function nodes give way to the slot's parameters.
            let rows = &self.rows;
            let detached: Vec<u16> = self.children[slot_row as usize]
                .iter()
                .copied()
                .filter(|&c| !matches!(rows[c as usize].name, Some("mode" | "name" | "$fname")))
                .collect();
            self.children[slot_row as usize].retain(|c| !detached.contains(c));
            self.detached.extend(detached);
            let slot = self.slots.len() as u16;
            for (k, &id) in ids.iter().enumerate() {
                self.by_id.insert(id, IdTarget::Param { slot, index: k as u8 + 1 });
            }
            self.slots.push(Slot { row: slot_row, family: if is_encoder { encoders } else { keys }, ids });
            self.slot_of_row.insert(slot_row, slot);
            self.cc_mode_rows.insert(slot, mode_row);
        }
    }

    /// The definition of a custom control function node.
    fn cc_def(&mut self, n: &CcNode, daw_btn_def: u16) -> u16 {
        let def = |ty, long_name| Def {
            ty,
            unit: unit::NONE,
            read_only: false,
            long_name,
            min: 0.0,
            max: 0.0,
            steps: 0,
            min_int: 0,
            max_int: 0,
            max_len: 0,
            enum_list: None,
        };
        let items: Vec<&'static str> = match n.values {
            CcValues::DawButtons => return daw_btn_def,
            CcValues::Int(min, max) => {
                self.defs.push(Def { min_int: min, max_int: max, ..def(NodeType::Int, n.long) });
                return (self.defs.len() - 1) as u16;
            }
            CcValues::Items(items) => items.to_vec(),
            CcValues::Numbered(lists) => lists
                .iter()
                .flat_map(|&(prefix, count)| match count {
                    0 => vec![prefix],
                    _ => (1..=count).map(|i| &*Box::leak(format!("{prefix}{i}").into_boxed_str())).collect(),
                })
                .collect(),
        };
        self.enums.push(EnumList {
            float: false,
            items: items.into_iter().map(|item| EnumItem { item, value: 0.0, long: item }).collect(),
        });
        self.defs.push(Def { enum_list: Some((self.enums.len() - 1) as u16), ..def(NodeType::StrEnum, n.long) });
        (self.defs.len() - 1) as u16
    }

    /// A custom control key's or encoder's slot: its `mode` row (None for
    /// every other slot).
    pub fn cc_mode_row(&self, slot: u16) -> Option<u16> {
        self.cc_mode_rows.get(&slot).copied()
    }

    /// True for the sweep's own custom control function rows, which the
    /// custom control slots' parameters replace (they are no node's child).
    pub fn is_detached(&self, row: u16) -> bool {
        self.detached.contains(&row)
    }

    /// Corrects what the parameter sweep caught in a state the console
    /// doesn't start in: CH 3's input delay was read in ms, while a
    /// factory-set WING describes every channel's in meters (its DLY MODE
    /// changes the unit, which `SF::Dly` handles).
    fn fix_sweep(&mut self) {
        let row = |s: &Schema, path: &str| match s.resolve(path, &NoModels) {
            Some(Node::Row(r)) => Some(r as usize),
            _ => None,
        };
        if let (Some(good), Some(bad)) = (row(self, "/ch/1/in/set/dly"), row(self, "/ch/3/in/set/dly")) {
            self.rows[bad].def = self.rows[good].def;
        }
    }

    pub fn num_rows(&self) -> usize {
        self.rows.len()
    }

    /// The slot whose node is `row`, if it holds models.
    pub fn slot_of(&self, row: u16) -> Option<u16> {
        self.slot_of_row.get(&row).copied()
    }

    pub fn family_of(&self, slot: u16) -> &Family {
        &self.families[self.slots[slot as usize].family as usize]
    }

    /// The index of `token` among `slot`'s models.
    pub fn model_index(&self, slot: u16, token: &str) -> Option<usize> {
        self.family_of(slot).models.iter().position(|m| m.token.eq_ignore_ascii_case(token))
    }

    fn param_of(&self, slot: u16, index: u8, models: &dyn ModelSource) -> Option<&ModelParam> {
        let m = models.active_model(slot)?;
        self.family_of(slot).models.get(m)?.params.iter().find(|p| p.index == index as u16)
    }

    pub fn def(&self, node: Node, models: &dyn ModelSource) -> Option<&Def> {
        match node {
            Node::Root => None,
            Node::Row(r) => self.defs.get(self.rows.get(r as usize)?.def as usize),
            Node::Param { slot, index } => self.defs.get(self.param_of(slot, index, models)?.def as usize),
        }
    }

    pub fn is_leaf(&self, node: Node, models: &dyn ModelSource) -> bool {
        self.def(node, models).is_some_and(Def::is_leaf)
    }

    pub fn id(&self, node: Node) -> u32 {
        match node {
            Node::Root => 0,
            Node::Row(r) => self.rows[r as usize].id,
            Node::Param { slot, index } => self.slots[slot as usize].ids.get(index as usize - 1).copied().unwrap_or(0),
        }
    }

    /// The node's index field (model parameters: their position).
    pub fn index(&self, node: Node) -> u16 {
        match node {
            Node::Root => 0,
            Node::Row(r) => self.rows[r as usize].index,
            Node::Param { index, .. } => index as u16,
        }
    }

    pub fn parent(&self, node: Node) -> Node {
        match node {
            Node::Root => Node::Root,
            Node::Row(r) => match self.rows[r as usize].parent {
                NO_PARENT => Node::Root,
                p => Node::Row(p),
            },
            Node::Param { slot, .. } => Node::Row(self.slots[slot as usize].row),
        }
    }

    /// The node's name in paths ("fdr", "1" for indexed nodes, "" for the root).
    pub fn name(&self, node: Node, models: &dyn ModelSource) -> Cow<'static, str> {
        match node {
            Node::Root => Cow::Borrowed(""),
            Node::Row(r) => {
                let row = &self.rows[r as usize];
                match row.name {
                    Some(n) => Cow::Borrowed(n),
                    None => Cow::Owned(row.index.to_string()),
                }
            }
            Node::Param { slot, index } => Cow::Borrowed(self.param_of(slot, index, models).map_or("", |p| p.name)),
        }
    }

    /// The node's own name field as the Native protocol sends it (empty for
    /// nodes addressed by index).
    pub fn wire_name(&self, node: Node, models: &dyn ModelSource) -> &'static str {
        match node {
            Node::Root => "",
            Node::Row(r) => self.rows[r as usize].name.unwrap_or(""),
            Node::Param { slot, index } => self.param_of(slot, index, models).map_or("", |p| p.name),
        }
    }

    /// Children in console order: static children, then the active model's parameters.
    pub fn children(&self, node: Node, models: &dyn ModelSource) -> Vec<Node> {
        match node {
            Node::Root => self.root_children.iter().map(|&r| Node::Row(r)).collect(),
            Node::Row(r) => {
                let mut out: Vec<Node> = self.children[r as usize].iter().map(|&c| Node::Row(c)).collect();
                if let Some(slot) = self.slot_of(r) {
                    if let Some(m) = models.active_model(slot).and_then(|m| self.family_of(slot).models.get(m)) {
                        out.extend(m.params.iter().map(|p| Node::Param { slot, index: p.index as u8 }));
                    }
                }
                out
            }
            Node::Param { .. } => Vec::new(),
        }
    }

    /// The static children of a row (no model parameters).
    pub fn static_children(&self, node: Node) -> &[u16] {
        match node {
            Node::Root => &self.root_children,
            Node::Row(r) => &self.children[r as usize],
            Node::Param { .. } => &[],
        }
    }

    pub fn child(&self, node: Node, name: &str, models: &dyn ModelSource) -> Option<Node> {
        let rows = self.static_children(node);
        for &c in rows {
            let row = &self.rows[c as usize];
            let hit = match row.name {
                Some(n) => n == name,
                None => name.parse::<u16>().ok() == Some(row.index),
            };
            if hit {
                return Some(Node::Row(c));
            }
        }
        if let Node::Row(r) = node {
            if let Some(slot) = self.slot_of(r) {
                let m = models.active_model(slot)?;
                let p = self.family_of(slot).models.get(m)?.params.iter().find(|p| p.name == name)?;
                return Some(Node::Param { slot, index: p.index as u8 });
            }
        }
        None
    }

    /// Resolves a path ("/ch/1/fdr"; the sweep's "/ch/1/gate/GATE/thr" form with
    /// an explicit model is accepted when that model is active).
    pub fn resolve(&self, path: &str, models: &dyn ModelSource) -> Option<Node> {
        let parts: Vec<&str> = path.split('/').filter(|p| !p.is_empty()).collect();
        let mut node = Node::Root;
        let mut i = 0;
        while i < parts.len() {
            if let Some(next) = self.child(node, parts[i], models) {
                node = next;
                i += 1;
                continue;
            }
            // An explicit model level ("GATE", "DEL/REV").
            let Node::Row(r) = node else { return None };
            let slot = self.slot_of(r)?;
            let active = models.active_model(slot)?;
            let token = self.family_of(slot).models.get(active)?.token;
            let n = token.split('/').count();
            if parts.len() >= i + n && parts[i..i + n].join("/") == token {
                i += n;
                continue;
            }
            return None;
        }
        Some(node)
    }

    /// Finds a node by id. Ids of model parameters are shared by every model
    /// of a slot: they resolve to the active model's parameter at that position.
    pub fn by_id(&self, id: u32, models: &dyn ModelSource) -> Option<Node> {
        if id == 0 {
            return Some(Node::Root);
        }
        match *self.by_id.get(&id)? {
            IdTarget::Row(r) => Some(Node::Row(r)),
            IdTarget::Param { slot, index } => {
                self.param_of(slot, index, models)?;
                Some(Node::Param { slot, index })
            }
        }
    }

    /// True if `id` names a model parameter position (whether or not the active model has it).
    pub fn is_param_id(&self, id: u32) -> bool {
        matches!(self.by_id.get(&id), Some(IdTarget::Param { .. }))
    }

    /// "/ch/1/fdr".
    pub fn path(&self, node: Node, models: &dyn ModelSource) -> String {
        let mut parts = Vec::new();
        let mut n = node;
        while n != Node::Root {
            parts.push(self.name(n, models));
            n = self.parent(n);
        }
        parts.reverse();
        let mut s = String::new();
        for p in parts {
            s.push('/');
            s.push_str(&p);
        }
        if s.is_empty() {
            s.push('/');
        }
        s
    }

    /// Path components of a row ("ch", "1", "fdr").
    pub fn row_parts(&self, row: u16) -> Vec<Cow<'static, str>> {
        let mut parts = Vec::new();
        let mut n = Node::Row(row);
        while n != Node::Root {
            parts.push(self.name(n, &NoModels));
            n = self.parent(n);
        }
        parts.reverse();
        parts
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    struct Fixed(usize);
    impl ModelSource for Fixed {
        fn active_model(&self, _: u16) -> Option<usize> {
            Some(self.0)
        }
    }

    #[test]
    fn tree_loads_and_resolves_known_ids() {
        let s = schema();
        assert!(s.num_rows() > 30000);
        // Ids from the protocol document: /ch/1/mute = 0xf50f69f8, /ch/1/fdr = 0x38ae75c2.
        let mute = s.resolve("/ch/1/mute", &NoModels).unwrap();
        assert_eq!(s.id(mute), 0xf50f69f8);
        assert_eq!(s.path(mute, &NoModels), "/ch/1/mute");
        let fdr = s.resolve("/ch/1/fdr", &NoModels).unwrap();
        assert_eq!(s.id(fdr), 0x38ae75c2);
        assert_eq!(s.def(fdr, &NoModels).unwrap().ty, NodeType::Fader);
        assert_eq!(s.by_id(0x38ae75c2, &NoModels), Some(fdr));
        assert_eq!(s.id(s.resolve("/$stat", &NoModels).unwrap()), 0x97a00439);
        let root: Vec<String> = s.children(Node::Root, &NoModels).iter().map(|&n| s.name(n, &NoModels).into_owned()).collect();
        assert_eq!(&root[..4], ["$stat", "cfg", "$syscfg", "io"]);
    }

    #[test]
    fn model_parameters_follow_the_active_model() {
        let s = schema();
        let gate = s.resolve("/ch/1/gate", &NoModels).unwrap();
        let Node::Row(r) = gate else { panic!() };
        let slot = s.slot_of(r).unwrap();
        let gate_model = s.model_index(slot, "GATE").unwrap();
        let thr = s.resolve("/ch/1/gate/thr", &Fixed(gate_model)).unwrap();
        assert!(matches!(thr, Node::Param { index: 1, .. }));
        assert_eq!(s.resolve("/ch/1/gate/GATE/thr", &Fixed(gate_model)), Some(thr));
        assert_eq!(s.path(thr, &Fixed(gate_model)), "/ch/1/gate/thr");
        // The id is shared with the same position of every other model.
        let id = s.id(thr);
        assert_eq!(id as i32, -1952441044);
        assert_eq!(s.by_id(id, &Fixed(gate_model)), Some(thr));
        assert!(s.resolve("/ch/1/gate/thr", &NoModels).is_none());
        // FX tokens with a slash.
        let fx = s.resolve("/fx/1", &NoModels).unwrap();
        let Node::Row(fr) = fx else { panic!() };
        let fslot = s.slot_of(fr).unwrap();
        let delrev = s.model_index(fslot, "DEL/REV").unwrap();
        assert!(s.resolve("/fx/1/time", &Fixed(delrev)).is_some());
        assert!(s.resolve("/fx/1/DEL/REV/time", &Fixed(delrev)).is_some());
    }
}
